'use client'

import { useEffect } from 'react'

/** Valor exacto de send_to del snippet de conversión de Google Ads: AW-xxxx/xxxx */
const adsConversionSendTo = process.env.NEXT_PUBLIC_GOOGLE_ADS_CONVERSION_SEND_TO?.trim()

/**
 * En sitio estático: al abrir /gracias se ejecuta en el cliente.
 * - dataLayer: útil si usas GTM (disparador por evento personalizado o por URL).
 * - gtag conversion: solo si cargaste gtag (Ads o GA) y definiste CONVERSION_SEND_TO.
 */
export function GraciasAnalytics() {
  useEffect(() => {
    if (typeof window === 'undefined') return
    const w = window as unknown as {
      dataLayer?: Record<string, unknown>[]
      gtag?: (...args: unknown[]) => void
    }
    w.dataLayer = w.dataLayer || []
    w.dataLayer.push({
      event: 'form_lead_complete',
      page_path: '/gracias',
    })

    if (adsConversionSendTo) {
      w.gtag?.('event', 'conversion', {
        send_to: adsConversionSendTo,
      })
    }
  }, [])
  return null
}
